    from {{ ref("ecommerce__order__checked_pre") }}
),
step_02_schema_transform as (
    select
        order_status,
        order_date,
        order_total,
        order_value_band,
        customer_business_key,
        cast(source_record_id as {{ dpf_type('string') }}) as order_record_id,
        cast(source_order_id as {{ dpf_type('string') }}) as order_id,
        cast(source_customer_id as {{ dpf_type('string') }}) as order_source_customer_id,
        cast(source_system as {{ dpf_type('string') }}) as order_source_system,
        cast(currency as {{ dpf_type('string') }}) as order_currency,
        cast(channel as {{ dpf_type('string') }}) as order_channel
    from checked_pre_input
),
step_03_data_enrichment as (
    select
        base.order_status,
        base.order_date,
        base.order_total,
        base.order_value_band,
        base.customer_business_key,
        base.order_record_id,
        base.order_id,
        base.order_source_customer_id,
        base.order_source_system,
        base.order_currency,
        base.order_channel,
        lookup_0.customer_external_id
    from step_02_schema_transform as base
    left join {{ ref("ecommerce__customer") }} as lookup_0
        on base.customer_business_key = lookup_0.customer_business_key
),
curation_records as (
    select
        order_status,
        order_date,
        order_total,
        order_value_band,
        customer_business_key,
        order_record_id,
        order_id,
        order_source_customer_id,
        order_source_system,
        order_currency,
        order_channel,
        customer_external_id,
        order_record_id as resolution_record_key
    from step_03_data_enrichment
),
curation_edges as (
    select
        resolution_record_key,
        1 as key_rank,
        'order_id' as key_name,
        'order_id:' || order_id as key_value
    from curation_records
    where order_id is not null
),
curation_labels_0 as (
    select distinct
        resolution_record_key,
        resolution_record_key as label
    from curation_edges
),
curation_values_1 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_0 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_1 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_1 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_values_2 as (
    select
        edges.key_value,
        min(labelled.label) as value_label
    from curation_edges as edges
    inner join curation_labels_1 as labelled
        on labelled.resolution_record_key = edges.resolution_record_key
    group by edges.key_value
),
curation_labels_2 as (
    select
        edges.resolution_record_key,
        min(matched.value_label) as label
    from curation_edges as edges
    inner join curation_values_2 as matched
        on matched.key_value = edges.key_value
    group by edges.resolution_record_key
),
curation_components as (
    select
        resolution_record_key,
        label as component_id
    from curation_labels_2
),
curation_component_stats as (
    select
        component_id,
        count(*) as component_row_count
    from curation_components
    group by component_id
),
curation_component_keys as (
    select
        components.component_id,
        min(edges.key_rank) as best_key_rank
    from curation_components as components
    inner join curation_edges as edges
        on edges.resolution_record_key = components.resolution_record_key
    group by components.component_id
),
curation_resolved as (
    select
        records.order_status,
        records.order_date,
        records.order_total,
        records.order_value_band,
        records.customer_business_key,
        records.order_record_id,
        records.order_id,
        records.order_source_customer_id,
        records.order_source_system,
        records.order_currency,
        records.order_channel,
        records.customer_external_id,
        records.resolution_record_key,
        coalesce(components.component_id, records.resolution_record_key) as resolution_entity_key,
        coalesce(stats.component_row_count, 1) as resolution_row_count,
        case
            when keys.best_key_rank = 1 then 'order_id'
        end as resolution_key_name,
        case
            when coalesce(stats.component_row_count, 1) > 1 then 'deterministic'
            else 'unresolved'
        end as resolution_tier,
        coalesce(stats.component_row_count, 1) = 1 as resolution_pending
    from curation_records as records
    left join curation_components as components
        on components.resolution_record_key = records.resolution_record_key
    left join curation_component_stats as stats
        on stats.component_id = components.component_id
    left join curation_component_keys as keys
        on keys.component_id = components.component_id
)

select
    order_status,
    order_date,
    order_total,
    order_value_band,
    customer_business_key,
    order_record_id,
    order_id,
    order_source_customer_id,
    order_source_system,
    order_currency,
    order_channel,
    customer_external_id,
    resolution_record_key,
    resolution_entity_key,
    resolution_row_count,
    resolution_key_name,
    resolution_tier,
    resolution_pending
from curation_resolved
